@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

:root {
  /* Colors in OKLCH */
  --brand-primary: oklch(35.5% 0.16 261); /* #003B95 */
  --brand-accent: oklch(50.8% 0.22 261);  /* #006CE4 */
  --brand-highlight: oklch(81% 0.18 80);  /* #FFB700 */
  --brand-highlight-hover: oklch(76% 0.18 80);
  --text-primary: oklch(20% 0.01 260);
  --text-secondary: oklch(45% 0.01 260);
  --bg-surface: oklch(98% 0.01 260);
  --bg-white: oklch(100% 0 0);
  --border-light: oklch(90% 0.01 260);
  --success-color: oklch(60% 0.15 140);

  /* Layout & Spacing */
  --container-width: 1140px;
  --spacing-xs: 4px;
  --spacing-sm: 8px;
  --spacing-md: 16px;
  --spacing-lg: 24px;
  --spacing-xl: 32px;
  --spacing-2xl: 48px;
  --spacing-3xl: 64px;

  /* Typography */
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;

  /* Borders & Shadows */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.12);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.16);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  color: var(--text-primary);
  background-color: var(--bg-surface);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a {
  color: var(--brand-accent);
  text-decoration: none;
  transition: color 0.2s;
}

a:hover {
  text-decoration: underline;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  display: block;
}

/* Container */
.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Typography */
h1 { font-size: 3rem; font-weight: 700; line-height: 1.2; margin-bottom: var(--spacing-sm); }
h2 { font-size: 2rem; font-weight: 700; line-height: 1.3; margin-bottom: var(--spacing-sm); }
h3 { font-size: 1.5rem; font-weight: 600; line-height: 1.4; margin-bottom: var(--spacing-xs); }
h4 { font-size: 1.25rem; font-weight: 600; line-height: 1.4; }
.subtitle { color: var(--text-secondary); font-size: 1.125rem; margin-bottom: var(--spacing-xl); }
.text-muted { color: var(--text-secondary); }
.text-small { font-size: 0.875rem; }

/* Header */
.site-header {
  background-color: var(--brand-primary);
  color: var(--bg-white);
  padding: var(--spacing-md) 0 0;
}

.header-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: var(--spacing-md);
}

.logo {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--bg-white);
  text-decoration: none;
}
.logo:hover {
  text-decoration: none;
}

.auth-buttons {
  display: flex;
  gap: var(--spacing-sm);
}

.btn {
  display: inline-block;
  padding: 10px 20px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  border: none;
  font-size: 1rem;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--brand-accent);
  color: var(--bg-white);
}

.btn-primary:hover {
  background-color: oklch(45% 0.22 261);
  text-decoration: none;
  color: white;
}

.btn-secondary {
  background-color: var(--bg-white);
  color: var(--brand-accent);
}

.btn-secondary:hover {
  background-color: var(--border-light);
  text-decoration: none;
}

.btn-highlight {
  background-color: var(--brand-highlight);
  color: var(--text-primary);
}

.btn-highlight:hover {
  background-color: var(--brand-highlight-hover);
  text-decoration: none;
}

.main-nav {
  display: flex;
  gap: var(--spacing-xs);
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: var(--spacing-sm);
}
.main-nav::-webkit-scrollbar {
  display: none;
}

.nav-link {
  color: var(--bg-white);
  padding: 10px 16px;
  border-radius: 20px;
  white-space: nowrap;
  font-weight: 500;
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-link:hover {
  background-color: rgba(255, 255, 255, 0.1);
  text-decoration: none;
}

.nav-link.active {
  background-color: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255,255,255,0.4);
}

/* Hero Section */
.hero {
  background-color: var(--brand-primary);
  color: var(--bg-white);
  padding: var(--spacing-2xl) 0 100px;
  position: relative;
}

.hero .subtitle {
  color: var(--bg-white);
  opacity: 0.9;
}

/* Search Form Component */
.search-container {
  background: var(--brand-highlight);
  padding: 4px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  margin-top: -30px;
  position: relative;
  z-index: 10;
  max-width: var(--container-width);
  margin-left: auto;
  margin-right: auto;
}

.search-form {
  display: flex;
  gap: 4px;
  background: var(--brand-highlight);
}

.search-field {
  flex: 1;
  background: var(--bg-white);
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 12px;
  position: relative;
  color: var(--text-primary);
}

.search-field input {
  border: none;
  outline: none;
  font-size: 1rem;
  width: 100%;
  font-family: inherit;
  color: var(--text-primary);
}

.search-btn {
  background-color: var(--brand-accent);
  color: var(--bg-white);
  border: none;
  font-size: 1.125rem;
  font-weight: 600;
  padding: 0 var(--spacing-xl);
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background-color 0.2s;
}

.search-btn:hover {
  background-color: oklch(45% 0.22 261);
}

.search-options {
  margin-top: var(--spacing-sm);
  display: flex;
  gap: var(--spacing-md);
  font-size: 0.875rem;
  color: var(--text-primary);
  font-weight: 500;
}

/* Radio buttons in Packages */
.radio-group {
  display: flex;
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-md);
  background: white;
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius-sm);
}

.radio-option {
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  color: var(--text-primary);
  font-weight: 500;
}

/* Sections */
.section {
  padding: var(--spacing-3xl) 0;
}

.section-light {
  background-color: var(--bg-white);
}

/* Trust Badges */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
}

.trust-badge {
  display: flex;
  gap: var(--spacing-sm);
  align-items: flex-start;
}
.trust-badge-icon {
  color: var(--brand-primary);
  flex-shrink: 0;
}
.trust-badge-title {
  font-weight: 600;
  margin-bottom: 4px;
}

/* Cards & Grids */
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--spacing-lg); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--spacing-lg); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--spacing-lg); }
.grid-5 { display: grid; grid-template-columns: repeat(5, 1fr); gap: var(--spacing-md); }
.grid-6 { display: grid; grid-template-columns: repeat(6, 1fr); gap: var(--spacing-md); }

@media (max-width: 992px) {
  .grid-4, .grid-5, .grid-6 { grid-template-columns: repeat(3, 1fr); }
  .search-form { flex-direction: column; }
}
@media (max-width: 768px) {
  .grid-2, .grid-3, .grid-4 { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .grid-2, .grid-3, .grid-4, .grid-5, .grid-6 { grid-template-columns: 1fr; }
}

.card {
  background: var(--bg-white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform 0.2s, box-shadow 0.2s;
  cursor: pointer;
  border: 1px solid var(--border-light);
  display: flex;
  flex-direction: column;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.card-img {
  width: 100%;
  height: 200px;
  object-fit: cover;
  background-color: var(--border-light);
}

.card-content {
  padding: var(--spacing-md);
  flex-grow: 1;
  display: flex;
  flex-direction: column;
}

.card-title {
  font-weight: 600;
  margin-bottom: 4px;
}

.card-rating {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
  margin-bottom: 8px;
  font-size: 0.875rem;
}

.badge {
  background-color: var(--brand-primary);
  color: var(--bg-white);
  padding: 4px 8px;
  border-radius: 4px;
  font-weight: 600;
}

.card-price {
  margin-top: auto;
  font-weight: 700;
  font-size: 1.125rem;
}

.price-strike {
  color: var(--text-secondary);
  text-decoration: line-through;
  font-size: 0.875rem;
  font-weight: normal;
  margin-right: 8px;
}

/* Tabs Component */
.tabs-header {
  display: flex;
  gap: var(--spacing-md);
  border-bottom: 1px solid var(--border-light);
  margin-bottom: var(--spacing-lg);
  overflow-x: auto;
  scrollbar-width: none;
}
.tabs-header::-webkit-scrollbar { display: none; }

.tab-btn {
  background: none;
  border: none;
  padding: var(--spacing-sm) 0;
  font-size: 1rem;
  color: var(--text-secondary);
  font-weight: 500;
  cursor: pointer;
  position: relative;
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--text-primary);
}

.tab-btn.active {
  color: var(--brand-accent);
}

.tab-btn.active::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 2px;
  background-color: var(--brand-accent);
}

.tab-pane {
  display: none;
}

.tab-pane.active {
  display: block;
  animation: fadeIn 0.3s;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Carousel */
.carousel-wrapper {
  position: relative;
}

.carousel {
  display: flex;
  gap: var(--spacing-md);
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  padding-bottom: var(--spacing-md);
}
.carousel::-webkit-scrollbar { display: none; }

.carousel-item {
  flex: 0 0 260px;
  scroll-snap-align: start;
}

.carousel-btn {
  position: absolute;
  top: 40%;
  transform: translateY(-50%);
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--bg-white);
  border: 1px solid var(--border-light);
  box-shadow: var(--shadow-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 2;
  transition: background-color 0.2s;
}

.carousel-btn:hover {
  background: var(--border-light);
}

.carousel-btn.prev { left: -20px; }
.carousel-btn.next { right: -20px; }

/* Accordion */
.accordion {
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  background: var(--bg-white);
}

.accordion-item {
  border-bottom: 1px solid var(--border-light);
}

.accordion-item:last-child {
  border-bottom: none;
}

.accordion-header {
  padding: var(--spacing-md);
  width: 100%;
  background: none;
  border: none;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  cursor: pointer;
  text-align: left;
}

.accordion-header:hover {
  background-color: var(--bg-surface);
}

.accordion-content {
  padding: 0 var(--spacing-md);
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out, padding 0.3s ease;
  color: var(--text-secondary);
}

.accordion-item.active .accordion-content {
  padding: 0 var(--spacing-md) var(--spacing-md);
  max-height: 200px;
}

.accordion-icon {
  transition: transform 0.3s;
}

.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
}

/* Promo Boxes */
.promo-box {
  background-color: var(--bg-white);
  border: 1px solid var(--border-light);
  border-radius: var(--radius-md);
  padding: var(--spacing-lg);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.promo-box h3 { margin-bottom: 8px; }

/* Offers Cards */
.offer-card {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: var(--spacing-lg);
  background: var(--bg-white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-light);
  background-size: cover;
  background-position: right center;
}

/* Footer */
.site-footer {
  background-color: var(--brand-primary);
  color: var(--bg-white);
  padding: var(--spacing-3xl) 0 var(--spacing-md);
  font-size: 0.875rem;
}

.footer-nav {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-xl);
  margin-bottom: var(--spacing-3xl);
}

.footer-nav h4 {
  margin-bottom: var(--spacing-md);
  font-size: 1rem;
}

.footer-nav ul {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.footer-nav a {
  color: var(--bg-white);
  text-decoration: none;
  opacity: 0.8;
}

.footer-nav a:hover {
  opacity: 1;
  text-decoration: underline;
}

.footer-bottom {
  text-align: center;
  padding-top: var(--spacing-xl);
  border-top: 1px solid rgba(255,255,255,0.1);
  opacity: 0.8;
}

/* Utilities */
.text-center { text-align: center; }
.mb-1 { margin-bottom: var(--spacing-sm); }
.mb-2 { margin-bottom: var(--spacing-md); }
.mb-3 { margin-bottom: var(--spacing-lg); }
.mb-4 { margin-bottom: var(--spacing-xl); }
.mt-4 { margin-top: var(--spacing-xl); }

.flex { display: flex; }
.items-center { align-items: center; }
.justify-between { justify-content: space-between; }
.gap-2 { gap: var(--spacing-md); }

/* Decorative images for categories */
.cat-img {
  width: 100%;
  height: 140px;
  object-fit: cover;
  border-radius: var(--radius-sm);
  margin-bottom: var(--spacing-sm);
}

.cat-card {
  cursor: pointer;
  transition: transform 0.2s;
}
.cat-card:hover {
  transform: translateY(-4px);
}
.cat-title {
  font-weight: 600;
}

.destination-card {
  position: relative;
  border-radius: var(--radius-md);
  overflow: hidden;
  height: 240px;
  cursor: pointer;
}
.destination-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,0.8) 0%, rgba(0,0,0,0) 50%);
  z-index: 1;
}
.destination-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.3s;
}
.destination-card:hover .destination-img {
  transform: scale(1.05);
}
.destination-content {
  position: absolute;
  bottom: 0;
  left: 0;
  padding: var(--spacing-md);
  color: white;
  z-index: 2;
}

/* Logos */
.logo-grid {
  display: flex;
  flex-wrap: wrap;
  gap: var(--spacing-xl);
  align-items: center;
  justify-content: center;
  opacity: 0.7;
}
.logo-item {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-secondary);
}

/* Loyalty CTA */
.loyalty-cta {
  background-color: var(--brand-primary);
  color: var(--bg-white);
  padding: var(--spacing-3xl) 0;
  text-align: center;
  border-radius: var(--radius-lg);
  margin: var(--spacing-3xl) 0;
}

.pill-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.pill {
  padding: 8px 16px;
  background: var(--bg-surface);
  border: 1px solid var(--border-light);
  border-radius: 20px;
  font-size: 0.875rem;
  color: var(--text-primary);
  cursor: pointer;
}
.pill:hover {
  background: var(--border-light);
}

.popular-links-list {
  column-count: 4;
  column-gap: var(--spacing-xl);
}
.popular-links-list li {
  margin-bottom: var(--spacing-sm);
}
.popular-links-list a {
  color: var(--text-primary);
  text-decoration: none;
}
.popular-links-list a:hover {
  color: var(--brand-accent);
  text-decoration: underline;
}

@media (max-width: 992px) {
  .popular-links-list { column-count: 3; }
}
@media (max-width: 768px) {
  .popular-links-list { column-count: 2; }
}
@media (max-width: 480px) {
  .popular-links-list { column-count: 1; }
}

