}

.section-light {
  background-color: var(--bg-white);
}

/* Trust Badges */
.trust-badges {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
}

.trust-badge {
  display: flex;
  gap: var(--spacing-sm);
  align-items: flex-start;
}
.trust-badge-icon {
